input.command:
cd /home/runner/work/personal-ai-os/personal-ai-os/projects/taste-memory; git checkout -qb factory/taste-memory/m5
python3 - <<'E'
p='public/index.html'; s=open(p).read()
a=s.index('<section class="card"><h2>O que ver/ler agora?'); b=s.index('<section class="card"><h2>Atualizar dados')
s=s[:a]+'''<section class="card"><h2 id="rech">Indicações para você</h2>
<p class="muted">O curador usa o que sabe do seu gosto (notas, favoritos, o que você marcou). Não precisa pedir nada.</p>
<button id="rec" class="primary">Me indique 5</button>
<details style="margin-top:10px"><summary class="muted">Quer direcionar? (opcional)</summary>
<label>Humor ou pedido <input id="mood" maxlength="200" placeholder="ex.: algo leve, curto, de suspense"></label></details>
<p id="recmsg" class="muted" aria-live="polite" role="status"></p><div id="recs"></div><div id="wants"></div></section>
'''+s[b:]
open(p,'w').write(s)
p='public/app.js'; s=open(p).read()
a=s.index('async function rec()'); b=s.index('$("rec").addEventListener')
s=s[:a]+'''async function rec() {
  const m = $("recmsg"), box = $("recs"), btn = $("rec"), kind = tab === "film" ? "filmes" : "livros";
  if (!db.items.some((i) => i.type === tab)) { m.className = "err"; m.textContent = `Ainda não tenho nenhum dos seus ${kind}. ${tab === "book" ? "Importe o CSV do Goodreads (seção abaixo)" : "Toque em “Atualizar agora” ou importe o CSV"} e tente de novo.`; return; }
  const t0 = Date.now(), label = btn.textContent;
  btn.disabled = true; box.innerHTML = ""; m.className = "muted";
  const tick = () => { const s = Math.round((Date.now() - t0) / 1000); btn.textContent = `⏳ Buscando… ${s}s`; m.textContent = `Analisando seus ${kind} e escolhendo 5 indicações (costuma levar de 5 a 20 segundos)…`; };
  tick(); const timer = setInterval(tick, 1000);
  try {
    const list = await recommend({ workerUrl, list: db.items, type: tab, mood: $("mood").value, feedback: db.feedback });
    cur = list; openChat = null; renderSugs();
    m.className = "ok"; m.textContent = `Pronto: ${list.length} indicações de ${kind} em ${Math.round((Date.now() - t0) / 1000)}s.`;
    box.scrollIntoView({ behavior: "smooth", block: "start" });
  } catch (e) { m.className = "err"; m.textContent = e.message; }
  clearInterval(timer); btn.textContent = label; btn.disabled = false;
}
'''+s[b:]
open(p,'w').write(s)
E
grep -n "Recomendar\|#rec\|O que ver" qa_m*.py app/test/*.mjs | head -20; sed -n 60,100p qa_m4.py

